using System.ComponentModel;
using System.Net.Http.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class FetchDataTool
{
    [McpServerTool("fetch_post"), Description("Fetches a post by ID from an external API")]
    public static async Task<string> FetchPost(
        IHttpClientFactory httpClientFactory,
        [Description("The numeric ID of the post to fetch")] int id)
    {
        var client = httpClientFactory.CreateClient("ExternalApi");
        var post = await client.GetFromJsonAsync<Post>($"/posts/{id}");

        if (post is null)
            return "Post not found.";

        return $"""
            Title: {post.Title}
            Body: {post.Body}
            """;
    }

    private record Post(int Id, int UserId, string Title, string Body);
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Generates a prompt to summarize the given text")]
    public static IList<PromptMessage> Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Optional desired length: short, medium, or long")] string length = "medium")
    {
        var systemInstruction = length switch
        {
            "short" => "Summarize in 1-2 sentences.",
            "long" => "Provide a detailed summary covering all key points.",
            _ => "Provide a concise summary in a short paragraph."
        };

        return
        [
            new PromptMessage
            {
                Role = "user",
                Content = new() { Type = "text", Text = $"{systemInstruction}\n\nText to summarize:\n{text}" }
            }
        ];
    }
}

